import { useState } from "react";
import CheckRow from "./CheckRow";

function scoreColor(score) {
  if (score >= 80) return "text-pass";
  if (score >= 50) return "text-warn";
  return "text-fail";
}

function buildReportText(result) {
  const lines = [
    `Site diagnostics report`,
    `Target:    ${result.target}`,
    `Run at:    ${result.timestamp}`,
    `Score:     ${result.score}/100`,
    "",
    ...result.checks.map(
      (c) =>
        `[${c.severity.toUpperCase()}] ${c.title}\n  ${c.summary}${c.detail ? `\n  ${c.detail}` : ""}`
    ),
    "",
    "Generated by a non-intrusive header/TLS/path/DNS check. Re-run periodically.",
  ];
  return lines.join("\n");
}

export default function ResultsReport({ result }) {
  const [collapsed, setCollapsed] = useState(false);

  if (!result) return null;

  const counts = result.checks.reduce(
    (acc, c) => ({ ...acc, [c.severity]: (acc[c.severity] || 0) + 1 }),
    {}
  );

  function download() {
    const blob = new Blob([buildReportText(result)], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `diagnostics-${result.hostname}.txt`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  }

  return (
    <div className="mt-6">
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div>
          <p className="text-xs font-mono text-base-500">{result.target}</p>
          <div className="flex items-baseline gap-2 mt-1">
            <span className={`font-display text-4xl font-bold ${scoreColor(result.score)}`}>
              {result.score}
            </span>
            <span className="text-base-500 text-sm">/ 100</span>
          </div>
          <p className="text-xs text-base-500 mt-1 font-mono">
            {counts.fail || 0} fail · {counts.warn || 0} warn · {counts.pass || 0} pass
          </p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={download}
            className="border border-base-600 text-base-100 text-sm font-display px-4 py-2.5 rounded-md
                       hover:bg-base-800 active:scale-[0.98] transition"
          >
            Download report.txt
          </button>
          <button
            onClick={() => setCollapsed((c) => !c)}
            className="sm:hidden border border-base-600 text-base-100 text-sm font-display px-4 py-2.5 rounded-md"
            aria-expanded={!collapsed}
          >
            {collapsed ? "Show" : "Hide"}
          </button>
        </div>
      </div>

      {!collapsed && (
        <ul className="mt-5 divide-y divide-base-800">
          {result.checks.map((c) => (
            <CheckRow key={c.id} check={c} />
          ))}
        </ul>
      )}
    </div>
  );
}
